function concDespPropor(dias){
  const todosFx=fluxoLoad();
  const limite=dias?new Date(Date.now()-dias*864e5).toISOString().slice(0,10):'0000-00-00';
  // Transferência interna = saída numa conta com entrada de mesmo valor (±3 dias) na OUTRA conta
  // (ex.: InfinitePay → Santander), ou texto com o CNPJ da própria clínica.
  const entradas=todosFx.filter(m=>m.tipo==='entrada');
  const ehInterno=m=>/56616870000144/.test(m.desc||'')||entradas.some(e=>e.origem!==m.origem&&Math.abs(e.valor-m.valor)<0.005&&concDias(e.data,m.data)<=3);
  const fx=todosFx.filter(m=>m.tipo==='saida'&&m.valor>0&&!m.conc&&m.data>=limite);
  const desps=finLoad(FK.DESP);
  const ign=concIgnLoad();
  const usados=new Set(desps.filter(d=>d.concFx).map(d=>d.id));
  const ex={interno:0,fatura:0,repasse:0,regra:0};
