        ${semDesc?`<br><span style="color:#92400E">⚠️ ${semDesc} saída${semDesc>1?'s':''} veio${semDesc>1?'ram':''} sem descrição na leitura do PDF — por isso estão desmarcadas. Confira o extrato e informe a descrição antes de lançar.</span>`:''}
        ${exTxt?`<br><span style="color:var(--text3)">Fora da análise: ${exTxt}.</span>`:''}
      </div>
      ${r.novas.length?`<div style="padding:10px 16px 4px;font-weight:600;font-size:13px">⚠️ Pagas no banco e não lançadas (${r.novas.length})</div>
      <table style="width:100%;border-collapse:collapse"><thead><tr style="background:var(--surface2);font-size:11px;color:var(--text3)"><th style="width:30px"></th><th style="padding:6px 8px;text-align:left">Data</th><th style="padding:6px 8px;text-align:left">Descrição (editável)</th><th style="padding:6px 8px;text-align:right">Valor</th><th style="padding:6px 8px;text-align:left">Categoria</th><th></th></tr></thead><tbody>${lNov}</tbody></table>`:''}
      ${r.casadas.length?`<div style="padding:14px 16px 4px;font-weight:600;font-size:13px">✅ Já lançadas — marcar como pagas (${r.casadas.length})</div>
      <table style="width:100%;border-collapse:collapse"><thead><tr style="background:var(--surface2);font-size:11px;color:var(--text3)"><th style="width:30px"></th><th style="padding:6px 8px;text-align:left">Data</th><th style="padding:6px 8px;text-align:left">Saída no extrato</th><th style="padding:6px 8px;text-align:right">Valor</th><th style="padding:6px 8px;text-align:left">Despesa lançada</th><th style="padding:6px 8px">Confiança</th></tr></thead><tbody>${lCas}</tbody></table>`:''}
    </div>
    <div class="modal-footer"><button class="btn-ghost" onclick="document.getElementById('modal-conc').remove()">Agora não</button>
      <button class="btn-save-purple" onclick="concDespAplicar()">✓ Aplicar selecionadas</button></div>
  </div>`;
  document.body.appendChild(mo);
  setTimeout(()=>mo.classList.add('open'),10);
}

function concDespIgnorar(i){
  const p=window._concD&&window._concD.novas[i]; if(!p) return;
  const ch=concChaveIgn(p.m.desc);
  if(!ch){ toast('Não consegui criar uma regra para esta descrição.'); return; }
  const l=concIgnLoad(); if(!l.includes(ch)){ l.push(ch); store(CONC_IGN_KEY,l); }
  p.ignorada=true;
  const tr=document.getElementById('cd-nrow-'+i); if(tr) tr.remove();
  toast('Saídas como "'+p.m.desc.slice(0,30)+'" não serão mais mostradas.');
}

function concDespAplicar(){
  const r=window._concD; if(!r) return;
  const desps=finLoad(FK.DESP), fx=fluxoLoad();
  let nPagas=0, nNovas=0;
  document.querySelectorAll('.cd-cas').forEach(c=>{
    if(!c.checked) return;
    const p=r.casadas[+c.dataset.i]; if(!p) return;
    const d=desps.find(x=>x.id===p.d.id); if(!d) return;
    d.pago=true; d.dataPagamento=p.m.data; d.concFx=p.m.id;
    const f=fx.find(x=>x.id===p.m.id); if(f) f.conc=[d.id];
    nPagas++;
  });
  document.querySelectorAll('.cd-nov').forEach(c=>{
    if(!c.checked) return;
    const i=+c.dataset.i, p=r.novas[i]; if(!p||p.ignorada) return;
    const desc=(document.getElementById('cd-desc-'+i)?.value||p.m.desc).trim();
    const cat=document.getElementById('cd-cat-'+i)?.value||p.cat;
    const id=Date.now()+i+(Math.random()*100|0);
    desps.push({id,desc,cat,valor:p.m.valor,data:p.m.data,vencimento:p.m.data,dataPagamento:p.m.data,tipo:'unica',grupoId:'g_'+id,parcelaAtual:1,totalParcelas:1,pago:true,importado:true,origemBanco:true,concFx:p.m.id});
    const f=fx.find(x=>x.id===p.m.id); if(f) f.conc=[id];
    nNovas++;
  });
  if(!nPagas&&!nNovas){ toast('Nada selecionado.'); return; }
  finSave(FK.DESP,desps); fluxoSave(fx);
  document.getElementById('modal-conc')?.remove();
  fin_refresh(); if(typeof finRenderFluxoCaixa==='function') finRenderFluxoCaixa();
  toast('✓ '+nPagas+' despesa'+(nPagas!==1?'s':'')+' marcada'+(nPagas!==1?'s':'')+' como paga'+(nPagas!==1?'s':'')+' · '+nNovas+' nova'+(nNovas!==1?'s':'')+' lançada'+(nNovas!==1?'s':'')+'.');
}
